using System.Net;using System.Text.Json;using MechanicalDesigns.Application.Common;using Microsoft.EntityFrameworkCore;
namespace MechanicalDesigns.Api.Middleware;
public sealed class ExceptionHandlingMiddleware(RequestDelegate next,ILogger<ExceptionHandlingMiddleware> logger){public async Task Invoke(HttpContext context){try{await next(context);}catch(Exception ex){logger.LogError(ex,"Unhandled request failure. TraceId: {TraceId}",context.TraceIdentifier);var(status,message)=ex switch{ConflictException=>(HttpStatusCode.Conflict,ex.Message),DbUpdateConcurrencyException=>(HttpStatusCode.Conflict,"The record changed concurrently. Reload and try again."),UnauthorizedException=>(HttpStatusCode.Unauthorized,ex.Message),ArgumentException=>(HttpStatusCode.BadRequest,ex.Message),_ =>(HttpStatusCode.InternalServerError,"An unexpected error occurred.")};context.Response.StatusCode=(int)status;context.Response.ContentType="application/json";await context.Response.WriteAsync(JsonSerializer.Serialize(new{success=false,message,errors=(object?)null,traceId=context.TraceIdentifier}));}}}
